import * as cheerio from "cheerio";
import { ExtractorField, FieldDiagnostic, SelectorChain } from "./types.js";
import { applyTransforms } from "./transforms.js";

export type CheerioSelection = ReturnType<cheerio.CheerioAPI>;

/**
 * Calculates selector resilience score (0-100) based on stability heuristics.
 */
export function calculateResilienceScore(selector: string): number {
  if (!selector) return 0;

  // 1. Data attributes are highest stability (tests, identifiers)
  if (selector.includes("[data-")) {
    return 95;
  }

  // 2. Stable IDs without autogenerated hashes
  if (selector.startsWith("#") && !/([a-z0-9]{8,}|_[0-9]{3,})/.test(selector)) {
    return 85;
  }

  // 3. Meaningful semantic classes (BEM or descriptive names)
  if (selector.startsWith(".") && !selector.includes(":nth-child") && !selector.includes(">")) {
    return 75;
  }

  // 4. Moderate structural CSS
  if (selector.includes(">") && !selector.includes(":nth-child")) {
    return 60;
  }

  // 5. Brittle nth-child or structural XPath
  if (selector.includes(":nth-child") || selector.startsWith("//") || selector.startsWith("/html")) {
    return 35;
  }

  return 50;
}

/**
 * Generates ranked selectors given an element and its attributes.
 */
export function generateRankedSelectors(
  tagName: string,
  attrs: Record<string, string>,
  textContent?: string,
): SelectorChain {
  const candidates: string[] = [];

  // Data attributes
  for (const [key, val] of Object.entries(attrs)) {
    if (key.startsWith("data-") && val) {
      candidates.push(`[${key}="${val}"]`);
    }
  }

  // ID
  if (attrs.id) {
    candidates.push(`#${attrs.id}`);
  }

  // Class names
  if (attrs.class) {
    const classes = attrs.class.trim().split(/\s+/).filter(Boolean);
    for (const c of classes) {
      // Ignore tailwind or short utility classes
      if (c.length > 3 && !/^[p|m|w|h|text|flex|grid|bg]-[a-z0-9]/.test(c)) {
        candidates.push(`.${c}`);
      }
    }
  }

  // Fallback to tag name
  candidates.push(tagName.toLowerCase());

  const primary = candidates[0] || tagName.toLowerCase();
  const fallback1 = candidates[1];
  const fallback2 = candidates[2];
  const textAnchor = textContent ? textContent.slice(0, 30).trim() : undefined;

  return {
    primary,
    fallback1,
    fallback2,
    textAnchor,
    resilienceScore: calculateResilienceScore(primary),
  };
}

/**
 * Extracts a value from a Cheerio container using primary selector or fallback chain.
 */
export function extractFieldWithFallback(
  container: CheerioSelection,
  field: ExtractorField,
  baseUrl?: string,
): { value: unknown; selectorUsed: FieldDiagnostic["selectorUsed"] } {
  const chain = field.selectors;

  // Try Primary
  let el = container.find(chain.primary);
  if (el.length > 0) {
    const raw = extractElementValue(el, field.type);
    if (raw !== null && raw !== undefined && raw !== "") {
      return {
        value: applyTransforms(raw, field.transforms, baseUrl),
        selectorUsed: "primary",
      };
    }
  }

  // Try Fallback 1
  if (chain.fallback1) {
    el = container.find(chain.fallback1);
    if (el.length > 0) {
      const raw = extractElementValue(el, field.type);
      if (raw !== null && raw !== undefined && raw !== "") {
        return {
          value: applyTransforms(raw, field.transforms, baseUrl),
          selectorUsed: "fallback1",
        };
      }
    }
  }

  // Try Fallback 2
  if (chain.fallback2) {
    el = container.find(chain.fallback2);
    if (el.length > 0) {
      const raw = extractElementValue(el, field.type);
      if (raw !== null && raw !== undefined && raw !== "") {
        return {
          value: applyTransforms(raw, field.transforms, baseUrl),
          selectorUsed: "fallback2",
        };
      }
    }
  }

  // Try Text Anchor heuristic
  if (chain.textAnchor) {
    const match = container.find(`*:contains("${chain.textAnchor}")`);
    if (match.length > 0) {
      const raw = match.first().text();
      return {
        value: applyTransforms(raw, field.transforms, baseUrl),
        selectorUsed: "textAnchor",
      };
    }
  }

  // Use default value if configured
  return {
    value: field.defaultValue ?? null,
    selectorUsed: "none",
  };
}

function extractElementValue(
  el: CheerioSelection,
  type: ExtractorField["type"],
): string | null {
  const first = el.first();
  if (!first.length) return null;

  if (type === "url") {
    return first.attr("href") || first.attr("src") || first.text().trim();
  }

  if (type === "image") {
    return first.attr("src") || first.attr("data-src") || first.attr("srcset") || null;
  }

  return first.text().trim();
}

/**
 * Extracts structured records from an HTML string according to fields configuration.
 */
export function extractRecordsFromHtml(
  html: string,
  fields: ExtractorField[],
  itemSelector?: string,
  baseUrl?: string,
): { records: Record<string, unknown>[]; diagnostics: FieldDiagnostic[] } {
  const $ = cheerio.load(html);
  const records: Record<string, unknown>[] = [];

  // Determine item containers
  const items = itemSelector ? $(itemSelector) : $("body");
  const totalItems = items.length;

  const stats: Record<string, { count: number; selectorUsed: FieldDiagnostic["selectorUsed"] }> = {};
  for (const f of fields) {
    stats[f.id] = { count: 0, selectorUsed: "none" };
  }

  items.each((_, elem) => {
    const container = $(elem);
    const row: Record<string, unknown> = {};

    for (const field of fields) {
      const { value, selectorUsed } = extractFieldWithFallback(container, field, baseUrl);
      row[field.name] = value;

      if (value !== null && value !== undefined && value !== "") {
        const fieldStat = stats[field.id];
        if (fieldStat) {
          fieldStat.count += 1;
          if (fieldStat.selectorUsed === "none") {
            fieldStat.selectorUsed = selectorUsed;
          }
        }
      }
    }

    records.push(row);
  });

  const diagnostics: FieldDiagnostic[] = fields.map((f) => {
    const extractedCount = stats[f.id]?.count ?? 0;
    const fillRate = totalItems > 0 ? Math.round((extractedCount / totalItems) * 100) : 0;
    const errors: string[] = [];

    if (f.required && extractedCount < totalItems) {
      errors.push(`Required field '${f.name}' was missing in ${totalItems - extractedCount} items.`);
    }

    return {
      fieldId: f.id,
      fieldName: f.name,
      totalTested: totalItems,
      extractedCount,
      fillRatePercent: fillRate,
      selectorUsed: stats[f.id]?.selectorUsed ?? "none",
      validationErrors: errors,
    };
  });

  return { records, diagnostics };
}
